def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Uniform full-span separator lines mark the grid's regions.
    rows = [r for r in range(h) if len(set(out[r])) == 1]
    cols = [c for c in range(w) if len({out[r][c] for r in range(h)}) == 1]
    for r in rows:
        out[r] = [2] * w
    for c in cols:
        for r in range(h):
            out[r][c] = 2
    return out

